async function scrapeMetaAds(keyword) {
  console.log(`[META] Buscando dataset para: "${keyword}"`);
  
  // Buscar dataset por nombre exacto o parcial
  const key = Object.keys(ADS_DATASETS).find(k => 
    k.toLowerCase() === keyword.toLowerCase() ||
    keyword.toLowerCase().includes(k.toLowerCase()) ||
    k.toLowerCase().includes(keyword.toLowerCase())
  );
  
  if (key) {
    const ads = ADS_DATASETS[key];
    console.log(`[META] Dataset encontrado: ${ads.length} anuncios para "${key}"`);
    return ads;
  }
  
  console.log(`[META] No hay dataset para "${keyword}" — devolviendo vacío`);
  return [];
}

// ── Generador de keyword Meta optimizada por Claude ──────────────────────────
async function generarKeywordMeta(productName) {
  const prompt = `Eres un experto en dropshipping y Meta Ads.
Tu tarea: dado el nombre de un producto detectado en TikTok, genera la keyword más efectiva para buscar anunciantes en Meta Ads Library.

Reglas:
1. La keyword debe ser semánticamente cercana al producto original
2. Usa términos que los anunciantes reales usan en sus campañas
3. NO uses términos demasiado genéricos (ej: "dog accessories" para "Dog Shoes" es incorrecto)
4. Máximo 4 palabras

Producto TikTok: "${productName}"

Responde ÚNICAMENTE con un JSON así (sin markdown):
{
  "meta_keyword": "la keyword optimizada",
  "alternatives": ["alternativa 1", "alternativa 2", "alternativa 3"],
  "reasoning": "por qué elegiste esta keyword en una frase"
}`;

  try {
    const res = await fetch('https://api.anthropic.com/v1/messages', {
      method: 'POST',
      headers: {
        'Content-Type': 'application/json',
        'x-api-key': ANTHROPIC_API_KEY,
        'anthropic-version': '2023-06-01',
      },
      body: JSON.stringify({
        model: 'claude-haiku-4-5-20251001',
        max_tokens: 200,
        messages: [{ role: 'user', content: prompt }],
      }),
    });
    const data  = await res.json();
    const text  = (data.content?.[0]?.text || '').trim();
    const clean = text.replace(/```json|```/g, '').trim();
    const parsed = JSON.parse(clean);
    console.log(`[KEYWORD] "${productName}" → "${parsed.meta_keyword}" (${parsed.reasoning})`);
    return {
      original_product: productName,
      meta_keyword:     parsed.meta_keyword,
      alternatives:     parsed.alternatives || [],
      reasoning:        parsed.reasoning || '',
    };
  } catch(e) {
    console.error('[KEYWORD ERROR]', e.message);
    // Fallback: usar el nombre original
    return {
      original_product: productName,
      meta_keyword:     productName.toLowerCase(),
      alternatives:     [],
      reasoning:        'fallback al nombre original',
    };
  }
}

// ── Familia comercial — 2 niveles ────────────────────────────────────────────
function generarFamilia(productName) {
  const familias = {
    'Kitchen Degreaser Spray':         { l1: ['degreaser','grease remover','kitchen degreaser','oil stain'], l2: ['kitchen cleaner','kitchen spray','oven cleaner'] },
    'Kitchen Gadget Assortment':       { l1: ['kitchen gadget','kitchen tool','cooking gadget'],             l2: ['kitchen accessory','home gadget','cooking tool'] },
    'Portable Dog Water Bottle':       { l1: ['dog water bottle','pet water bottle','dog travel water'],     l2: ['dog accessory','pet travel','dog outdoor'] },
    'Interactive Pet Ball':            { l1: ['pet ball','dog ball','cat ball','interactive pet toy'],        l2: ['pet toy','dog toy','cat toy'] },
    'Dog Shoes':                       { l1: ['dog shoes','dog boots','dog paw','pet shoes'],                l2: ['dog accessory','pet protection','dog gear'] },
    'HOVEAir X1 ProMax Drone':         { l1: ['hovear','self-flying drone','pocket drone','hand drone'],     l2: ['drone','flying camera','aerial camera'] },
    'Phone Stand':                     { l1: ['phone stand','phone holder','phone mount','desk phone'],      l2: ['phone accessory','desk accessory','mobile stand'] },
    'Pet Cooling Mat':                 { l1: ['cooling mat','pet cooling','dog cooling mat','cool pad'],     l2: ['pet mat','summer pet','dog summer'] },
    'Professional Juicer Machine':     { l1: ['juicer','cold press juicer','juice extractor','masticating'], l2: ['kitchen appliance','blender','smoothie maker'] },
    'AutoScooper 12 Lite':             { l1: ['autoscooper','auto litter','self cleaning litter','robot litter'], l2: ['litter box','cat litter','cat hygiene'] },
    'Portable Fan':                    { l1: ['portable fan','mini fan','personal fan','desk fan'],          l2: ['cooling fan','usb fan','battery fan'] },
    'Rotating Makeup Organizer':       { l1: ['makeup organizer','rotating organizer','cosmetic organizer'], l2: ['beauty organizer','vanity storage','makeup holder'] },
    'Keyboard with Built-in Trackpad': { l1: ['keyboard trackpad','wireless keyboard trackpad','keyboard touchpad'], l2: ['wireless keyboard','bluetooth keyboard','compact keyboard'] },
    'Black Shark Magnetic Cooler':     { l1: ['phone cooler','magnetic cooler','smartphone cooler'],         l2: ['phone cooling','mobile gaming','phone accessory'] },
  };
  // Fallback desde nombre
  const stop = new Set(['with','from','and','the','for','into','built','using','black','white','pro','max','lite']);
  const words = productName.toLowerCase().split(/[\s\-]+/).filter(w => w.length > 3 && !stop.has(w));
  return familias[productName] || { l1: words, l2: [] };
}

// ── Fase 1: Filtro barato por familia ────────────────────────────────────────
function filtroBarato(ad, familia) {
  const body    = (ad.ad_content?.body    || '').toLowerCase();
  const title   = (ad.ad_content?.title   || '').toLowerCase();
  const landing = (ad.ad_content?.link_url || ad.ad_content?.cards?.[0]?.link_url || '').toLowerCase();
  const texto   = [body, title, landing].join(' ');
  return [...familia.l1, ...familia.l2].some(kw => texto.includes(kw.toLowerCase()));
}

// ── Fase 2: Matching IA — SAME_FAMILY / RELATED_NICHE / UNRELATED ─────────
async function matchConIA(productName, ad) {
  const advertiser = ad.metadata?.page_name || '';
  const body       = ad.ad_content?.body    || '';
  const title      = ad.ad_content?.title   || '';
  const landing    = ad.ad_content?.link_url || ad.ad_content?.cards?.[0]?.link_url || '';
  const textoAd    = [body, title].filter(Boolean).join(' | ').slice(0, 400);

  const prompt = `Producto objetivo: ${productName}

Anuncio:
- Anunciante: ${advertiser}
- Texto: ${textoAd}
- Landing page: ${landing}

¿Este anuncio promociona un producto que un comprador potencial de "${productName}" consideraría como una alternativa, sustituto directo o producto muy relacionado?

Responde ÚNICAMENTE con una de estas tres opciones:
SAME_FAMILY
RELATED_NICHE
UNRELATED`;

  try {
    const res = await fetch('https://api.anthropic.com/v1/messages', {
      method: 'POST',
      headers: { 'Content-Type': 'application/json', 'x-api-key': ANTHROPIC_API_KEY, 'anthropic-version': '2023-06-01' },
      body: JSON.stringify({ model: 'claude-haiku-4-5-20251001', max_tokens: 10, messages: [{ role: 'user', content: prompt }] }),
    });
    const data  = await res.json();
    const reply = (data.content?.[0]?.text || '').trim().toUpperCase();
    if (reply.includes('SAME_FAMILY'))   return 'SAME_FAMILY';
    if (reply.includes('RELATED_NICHE')) return 'RELATED_NICHE';
    return 'UNRELATED';
  } catch(e) {
    console.error('[MATCH IA ERROR]', e.message);
    return 'UNRELATED';
  }
}

// ── Parsear un anuncio crudo ──────────────────────────────────────────────────
function parsearAnuncio(ad) {
  const now        = Date.now();
  const advertiser = ad.metadata?.page_name || '';
  const adText     = ad.ad_content?.body || ad.ad_content?.title || '';
  const landingRaw = ad.ad_content?.link_url || ad.ad_content?.cards?.[0]?.link_url || '';
  const startRaw   = ad.timing?.start_date || null;
  const archiveId  = ad.metadata?.ad_archive_id || ad.additional_info?.raw_data?.ad_archive_id || null;
  const metaUrl    = archiveId ? `https://www.facebook.com/ads/library/?id=${archiveId}` : null;

  let domain = '';
  try {
    if (landingRaw) domain = new URL(landingRaw.startsWith('http') ? landingRaw : `https://${landingRaw}`).hostname.replace('www.', '');
  } catch(_) { domain = landingRaw; }

  const isActive = ad.status?.is_active === true;
  // days_since_start: tiempo transcurrido desde que se lanzó el anuncio (NO es lo mismo que "días activo real")
  const days_since_start = startRaw ? Math.floor((now - startRaw * 1000) / 86400000) : null;
  const start_date_iso   = startRaw ? new Date(startRaw * 1000).toISOString().split('T')[0] : null;
  // real_active_days: SOLO tiene sentido si el anuncio sigue activo ahora. Si está parado, no sabemos cuánto duró
  // (Apify no expone end_date) — lo marcamos como "parado, duración desconocida" en vez de inventar un número.
  const real_active_days = isActive ? days_since_start : null;

  // Slug de la landing — para deduplicación de operadores
  let slug = '';
  try {
    const u = new URL(landingRaw.startsWith('http') ? landingRaw : `https://${landingRaw}`);
    slug = u.pathname.replace(/\/$/, '').toLowerCase();
  } catch(_) { slug = ''; }

  return { advertiser, adText, domain, landingRaw, slug, isActive, days_since_start, real_active_days, start_date_iso, archiveId, metaUrl };
}

// ── Calcular métricas con Product Match Engine ────────────────────────────────
async function calcularMetricas(ads, productName) {
  if (!ads || ads.length === 0) {
    return {
      total_ads_found: 0, matched_ads: 0, match_rate: 0,
      advertisers_total: 0, advertisers_matched: 0,
      valid_advertisers: 0, valid_domains: 0,
      oldest_match_days: null, avg_match_age_days: null,
      domains_matched: [], landing_pages: [], advertisers: [],
      meta_score_raw: 0, meta_score: 0, ads_raw: [],
    };
  }

  const familia = generarFamilia(productName);
  console.log(`[MATCH] Familia L1: [${familia.l1.join(', ')}] | L2: [${familia.l2.join(', ')}]`);

  // Un solo decision por anunciante
  const advertiserDecision = new Map(); // advertiser → 'SAME_FAMILY' | 'RELATED_NICHE' | 'UNRELATED'

  // Contadores por nivel
  const sfAdvertisers = new Set();  // SAME_FAMILY
  const rnAdvertisers = new Set();  // RELATED_NICHE
  const sfDomains     = new Set();
  const rnDomains     = new Set();
  let sf_ads = 0;
  let rn_ads = 0;
  const ads_raw = [];

  for (const ad of ads) {
    const p         = parsearAnuncio(ad);
    const pasaFase1 = filtroBarato(ad, familia);

    if (!pasaFase1) {
      ads_raw.push({ advertiser: p.advertiser, ad_text: p.adText.slice(0,200), domain: p.domain, landing: p.landingRaw, slug: p.slug, metaUrl: p.metaUrl, is_active: p.isActive, days_since_start: p.days_since_start, real_active_days: p.real_active_days, start_date: p.start_date_iso, match: 'UNRELATED', fase: 'NO_MATCH_FILTER' });
      continue;
    }

    // IA: una sola llamada por anunciante único
    let nivel;
    if (advertiserDecision.has(p.advertiser)) {
      nivel = advertiserDecision.get(p.advertiser);
    } else {
      nivel = await matchConIA(productName, ad);
      advertiserDecision.set(p.advertiser, nivel);
      console.log(`[MATCH IA] "${p.advertiser}" → ${nivel} (activo: ${p.isActive})`);
    }

    if (nivel === 'SAME_FAMILY') {
      sf_ads++;
      sfAdvertisers.add(p.advertiser);
      if (p.domain) sfDomains.add(p.domain);
    } else if (nivel === 'RELATED_NICHE') {
      rn_ads++;
      rnAdvertisers.add(p.advertiser);
      if (p.domain) rnDomains.add(p.domain);
    }

    ads_raw.push({ advertiser: p.advertiser, ad_text: p.adText.slice(0,200), domain: p.domain, landing: p.landingRaw, slug: p.slug, metaUrl: p.metaUrl, is_active: p.isActive, days_since_start: p.days_since_start, real_active_days: p.real_active_days, start_date: p.start_date_iso, match: nivel, fase: nivel });
  }

  // Anunciantes activos por nivel
  const activeAds     = ads_raw.filter(a => a.is_active);
  const activeSF      = activeAds.filter(a => a.match === 'SAME_FAMILY');
  const activeRN      = activeAds.filter(a => a.match === 'RELATED_NICHE');
  const activeSFAdvs  = new Set(activeSF.map(a => a.advertiser));
  const activeRNAdvs  = new Set(activeRN.map(a => a.advertiser));

  const advertisers_total    = [...new Set(ads.map(a => a.metadata?.page_name || '').filter(Boolean))].length;
  const advertisers_matched  = sfAdvertisers.size + rnAdvertisers.size;
  const valid_domains        = sfDomains.size;
  const match_rate           = Math.round(((sf_ads + rn_ads) / ads.length) * 100);

  // Métricas históricas vs activas (is_active del actor NO es fiable — se guarda pero no se usa en score)
  const historical_advertisers = sfAdvertisers.size;   // todos los SF detectados
  const active_advertisers_reported = activeSFAdvs.size; // según actor (no fiable)
  const active_ratio = historical_advertisers > 0
    ? Math.round((active_advertisers_reported / historical_advertisers) * 100)
    : 0;

  // Score: basado solo en señal histórica — is_active ignorado hasta validar fiabilidad
  const raw_score =
    (sfAdvertisers.size * 15) +   // anunciantes SAME_FAMILY (histórico)
    (sf_ads             *  1) +   // ads SAME_FAMILY
    (rnAdvertisers.size *  5) +   // anunciantes RELATED_NICHE
    (rn_ads             * 0.3);   // ads RELATED_NICHE

  // ── P4 corregido — Veteranía REAL ──────────────────────────────────────────
  // Solo cuenta como "veterano" un anuncio que SIGUE ACTIVO ahora mismo.
  // Si está parado, no inventamos cuánto duró (Apify no da end_date) — se marca como "parado".
  const sfAds = ads_raw.filter(a => a.match === 'SAME_FAMILY');
  const sfAdsConDuracionReal = sfAds.filter(a => a.real_active_days !== null && a.real_active_days !== undefined);
  const maxDays    = sfAdsConDuracionReal.length ? Math.max(...sfAdsConDuracionReal.map(a => a.real_active_days)) : null;
  const veteran90  = sfAdsConDuracionReal.filter(a => a.real_active_days >= 90).length;
  const veteran180 = sfAdsConDuracionReal.filter(a => a.real_active_days >= 180).length;

  // Anunciante más veterano (solo entre los REALMENTE activos)
  const veteranAdv = {};
  sfAdsConDuracionReal.forEach(a => {
    if (!veteranAdv[a.advertiser] || a.real_active_days > veteranAdv[a.advertiser].days) {
      veteranAdv[a.advertiser] = { days: a.real_active_days, start_date: a.start_date };
    }
  });
  const topVeteran = Object.entries(veteranAdv).sort((x,y) => y[1].days - x[1].days)[0];

  // ── P1 — Motor de deduplicación de landings (operadores independientes) ────
  // Score de similitud entre cada par de landings SAME_FAMILY: slug +40, título +20, copy +10-20
  // Agrupa landings con score >80 como "mismo operador"
  function normalizeText(s) { return (s || '').toLowerCase().replace(/[^a-z0-9 ]/g, ' ').replace(/\s+/g, ' ').trim(); }
  function textSimilarity(a, b) {
    const wa = new Set(normalizeText(a).split(' ').filter(w => w.length > 3));
    const wb = new Set(normalizeText(b).split(' ').filter(w => w.length > 3));
    if (wa.size === 0 || wb.size === 0) return 0;
    let common = 0;
    wa.forEach(w => { if (wb.has(w)) common++; });
    return common / Math.max(wa.size, wb.size); // 0..1
  }

  // Construimos un "landing" único por anunciante SF (la primera que aparece)
  const sfByAdvertiser = new Map();
  sfAds.forEach(a => {
    if (!sfByAdvertiser.has(a.advertiser)) sfByAdvertiser.set(a.advertiser, a);
  });
  const landingsList = [...sfByAdvertiser.values()];

  // Union-Find simple para agrupar
  const parent = landingsList.map((_, i) => i);
  function find(i) { while (parent[i] !== i) i = parent[i]; return i; }
  function union(i, j) { const ri = find(i), rj = find(j); if (ri !== rj) parent[ri] = rj; }

  for (let i = 0; i < landingsList.length; i++) {
    for (let j = i + 1; j < landingsList.length; j++) {
      const A = landingsList[i], B = landingsList[j];
      let score = 0;
      // Slug idéntico y no vacío es la señal más fuerte de clonación (ej. mismo /pages/news-interactive-...)
      if (A.slug && B.slug && A.slug === B.slug) score += 40;
      const titleSim = textSimilarity(A.ad_text.split('\n')[0] || '', B.ad_text.split('\n')[0] || '');
      score += Math.round(titleSim * 20);
      const copySim = textSimilarity(A.ad_text, B.ad_text);
      score += Math.round(copySim * 40); // copy es la señal más disponible sin scraping de precio/imagen
      if (score >= 80) union(i, j);
    }
  }

  const groups = new Map(); // root → [landings]
  landingsList.forEach((l, i) => {
    const root = find(i);
    if (!groups.has(root)) groups.set(root, []);
    groups.get(root).push(l);
  });

  const operadoresIndependientes = groups.size;
  const gruposClonados = [...groups.values()].filter(g => g.length > 1).map(g => ({
    operadores: g.map(l => l.advertiser),
    slug_compartido: g[0].slug || null,
  }));

  console.log(`[MATCH] "${productName}" → SF: ${sfAdvertisers.size}adv/${sf_ads}ads | RN: ${rnAdvertisers.size}adv/${rn_ads}ads | operadores_independientes: ${operadoresIndependientes} | veteranos_reales(>90d activos): ${veteran90} | score_raw=${raw_score}`);

  // ── Criterio de paso a Trends (definido por Laura) ──────────────────────────
  const cumpleCriterioOperadores = operadoresIndependientes >= 3;
  const cumpleCriterioVeterano   = veteran90 >= 1;
  const pasaATrends = cumpleCriterioOperadores || cumpleCriterioVeterano;

  return {
    total_ads_found:    ads.length,
    matched_ads:        sf_ads + rn_ads,
    same_family_ads:    sf_ads,
    related_niche_ads:  rn_ads,
    match_rate,
    advertisers_total,
    advertisers_matched,
    same_family_advertisers:    sfAdvertisers.size,
    related_niche_advertisers:  rnAdvertisers.size,
    historical_advertisers,
    active_advertisers_reported,
    active_ratio,
    valid_advertisers:  sfAdvertisers.size,
    valid_domains,
    domains_matched:    [...sfDomains, ...rnDomains],
    landing_pages:      [...sfDomains],
    advertisers:      [...sfAdvertisers, ...rnAdvertisers],
    meta_score_raw:   raw_score,
    meta_score:       0,
    // P4 — Veteranía REAL (solo activos)
    max_days_active:  maxDays,
    ads_veteran_90:   veteran90,
    ads_veteran_180:  veteran180,
    top_veteran:      topVeteran ? { advertiser: topVeteran[0], days: topVeteran[1].days, start_date: topVeteran[1].start_date } : null,
    // P1 — Deduplicación de operadores
    operadores_independientes: operadoresIndependientes,
    grupos_clonados: gruposClonados,
    // Decisión final
    cumple_criterio_operadores: cumpleCriterioOperadores,
    cumple_criterio_veterano: cumpleCriterioVeterano,
    pasa_a_trends: pasaATrends,
    ads_raw,
  };
}

// ── Normalizar meta_score a 0-100 ─────────────────────────────────────────────
function normalizarScores(productos) {
  const raws = productos.map(p => p.meta?.meta_score_raw || 0);
  const max  = Math.max(...raws, 1);
  return productos.map(p => ({
    ...p,
    meta: p.meta ? { ...p.meta, meta_score: Math.round((p.meta.meta_score_raw / max) * 100) } : p.meta,
  }));
}

// ── Score final combinado ─────────────────────────────────────────────────────
function calcularScoreFinal(productos) {
  return productos.map(p => ({
    ...p,
    score_final: p.meta
      ? Math.round(((p.tiktok_score / 100) * 60 + (p.meta.meta_score / 100) * 40) * 100) / 100
      : p.tiktok_score * 0.6,
  })).sort((a, b) => b.score_final - a.score_final);
}

